import { registerHooks } from 'node:module';
const root = new URL('./', import.meta.url);
registerHooks({resolve(specifier, context, nextResolve) {
  if (context.parentURL?.startsWith(root.href) && specifier.startsWith('.') && specifier.endsWith('.js')) {
    const url = new URL(specifier, context.parentURL);
    if (url.href.startsWith(new URL('src/', root).href) || url.href === new URL('dist/typed/vendor.js', root).href)
      return nextResolve(url.href.replace('/dist/typed/vendor.js', '/src/typed/vendor.ts').replace(/\.js$/, '.ts'), context);
  }
  return nextResolve(specifier, context);
}});
const {installVendor} = await import('./tools/node-vendor.mjs');
await installVendor({reference:true});
const {Program} = await import('./src/typed/program.ts');
const {projectSource} = await import('./src/typed/project.ts');
const {storeOf} = await import('./src/typed/ir.ts');
const {casesFrom,evaluate,agrees} = await import('./src/typed/evaluate.ts');
const B = await import('./src/typed/backend/index.ts');
const {BindingsIR} = await import('./src/typed/specialize.ts');
const {createArtifact} = await import('./src/framework/core/artifact.ts');
const source = \`
function bits(a: i32, b: i32, c: i32): i32 { return ((a * 31 + b) * 31 + c) & 15; }
function probe(input: buffer, output: buffer, cap: i32): i32 {
  const temp = new Int32Array(16);
  let i = 0;
  let total = 0;
  while (i < cap && i + 1 <= input.length) {
    const b = input.charCodeAt(i);
    const h = bits(b, 65, 66);
    temp[h] = temp[h] + 1;
    output.setCharCodeAt(i, 128 | ((temp[h] - 1) << 5) | (b & 31));
    const byte = output.charCodeAt(i);
    total = total + ((byte >>> 5) & 3);
    i = i + 1;
  }
  return total;
}
function rootCall(input: buffer, output: buffer, cap: i32): i32 {
  const result = probe(input, output, cap);
  return result;
}
function fixture(input: buffer): i32 { return input.charCodeAt(0); }
\`;
const input = {input:{buffer:[0,24],cell:[65,66]}, output:{buffer:[24,24],cell:[0,0]}, cap:[1,3]};
const spec = {sources:['main.typed'],pipeline:'speed',inputs:{probe:input,rootCall:input,bits:{a:[0,127],b:[0,127],c:[0,127]},fixture:{input:{cells:[65,224,66,192,127]}}}};
const ps = projectSource('feature-probe',{'main.typed':source,'project.json':JSON.stringify(spec)});
const p = Program.fromProject(ps);
console.log('ingest',p.status,p.error,p.fns());
if (p.status !== 'ok') process.exit(1);
const st = storeOf(p.origin.value);
console.log('frame bytes',st.fn('probe').arrayBytes);
const run = p.exec('rootCall', [[65,65],[0,0],2],{limit:2e4});
console.log('rootCall concrete',run.result,run.steps,run.buffers.map(b=>b.cells),run.trap);
const cases = casesFrom(st,'rootCall',{count:40,seed:7,inputs:p.inputs.rootCall});
console.log('generation',cases.length, Math.min(...cases.map(c=>c.items[0].length)),Math.max(...cases.map(c=>c.items[0].length)), [...new Set(cases.map(c=>c.args[2]))].sort(), p.cases('fixture',{count:1})[0].items);
const pass = await p.pipeline('speed');
console.log('speed',pass.steps.filter(s=>s.changed).map(s=>s.pass),pass.steps.filter(s=>s.rejected),p.check({count:40}).fns.map(f=>[f.fn,f.agree,f.inconclusive,f.bothTrap]));
const ref = globalThis.typedRv32.compile(ps.source, [], undefined);
const image = B.imageFromCode('feature-probe',ref.image,ref.entries);
const ours = B.lowerToImage(p.head,{chains:true,coalesce:true,homes:true}).image;
for (const [name,img] of [['reference',image],['ours',ours]]) {
  const runs = cases.map(c=>B.runImage(img,c.fn,c.args,c.memory,{limit:2e5}));
  console.log(name,runs.filter((r,i)=>!r.limit && agrees(evaluate(st,cases[i].fn,cases[i].args,cases[i].memory,{limit:2e4}),r)).length,runs[0].steps);
}
const q = Program.fromProject(ps);
const art = createArtifact(BindingsIR,'probe-cap',{formatVersion:1,source:'probe',bindings:['probe','rootCall'].map(fn=>({fn,param:'cap',value:3,entity:fn+'/cap'}))});
const specialized = await q.specialize(art);
console.log('specialization',specialized.changed,q.inputs.probe.cap,q.inputs.rootCall.cap,q.check({count:40}).fns.map(f=>[f.fn,f.agree,f.inconclusive]));
