node --experimental-transform-types --input-type=module <<'NODE'
import {registerHooks} from 'node:module';
const root = new URL('./', import.meta.url).href;
registerHooks({resolve(s,c,next) {
  if (c.parentURL?.startsWith(root) && s.startsWith('.') && s.endsWith('.js')) {
    const u = new URL(s,c.parentURL).href;
    if (u.startsWith(root + 'src/') || u === root + 'dist/typed/vendor.js')
      return next(u.replace('/dist/typed/vendor.js','/src/typed/vendor.ts').replace(/\.js$/,'.ts'),c);
  }
  return next(s,c);
}});
const {installVendor} = await import('./tools/node-vendor.mjs');
await installVendor();
const {createWb} = await import('./src/workbench/workbench.ts');
const wb = createWb({projects:[{id:'frame-probe',files:{
 'project.json':JSON.stringify({sources:['main.typed'],pipeline:'speed',ingest:{tape:true},inputs:{f:{out:{buffer:[1,1],cell:[0,0]}}},scripts:{smoke:{fresh:true}}}),
 'main.typed':'function f(out: buffer): i32 { const x = new Int32Array(1); out.setCharCodeAt(0, x[0] + 7); return out.charCodeAt(0); }',
 'scripts/smoke.js':"return p.compile().run('f', [[0]]);"
}}]});
const project = wb.projects.open('frame-probe');
const result = await project.run('smoke');
console.log(project.program.status, JSON.stringify(result));
